    juce::TextButton renderFx{"RENDER FX"},renderMix{"RENDER MIX"};ExportDrag dragWav;juce::TextButton learn{"LEARN"},apply{"APPLY"},undo{"UNDO"},preview{"PREVIEW"},bypass{"BYPASS"},previous{"<"},next{">"};std::array<juce::TextButton,3>variants;
    juce::ComboBox preset,delayRate,exportPart;std::unique_ptr<juce::AudioProcessorValueTreeState::ComboBoxAttachment>delayRateAttachment;std::array<juce::Slider,3>sends;std::array<juce::Label,3>sendLabels;std::vector<std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment>>sendAttachments;juce::Label status;std::array<juce::Slider,3>trim;std::array<juce::Label,3>trimLabel;
