        owner.setLookAndFeel(&look);wood=juce::ImageCache::getFromMemory(BinaryData::core_reference_png,BinaryData::core_reference_pngSize);
        owner.addAndMakeVisible(timeline);owner.addAndMakeVisible(quality);owner.addAndMakeVisible(status);status.setFont(font(11,true));status.setColour(juce::Label::textColourId,ink);
        for(auto*button:{&learn,&apply,&undo,&preview,&bypass,&previous,&next,&renderFx,&renderMix}){button->setName(button->getButtonText());button->setComponentID(button->getButtonText().toLowerCase());owner.addAndMakeVisible(button);}
        owner.addAndMakeVisible(dragWav);renderFx.setComponentID("renderFx");renderMix.setComponentID("renderMix");renderFx.onClick=[this]{p.renderEffects(true,p.kind==CreativeKind::Phrase?exportPart.getSelectedId()-1:0);};renderMix.onClick=[this]{p.renderEffects(false);};renderFx.setTooltip("RENDER THE EFFECTS WITHOUT THE DRY VOCAL. INCLUDES TAILS. DRAG THE FINISHED WAV INTO YOUR PLAYLIST.");renderMix.setTooltip("RENDER THE COMPLETE VOCAL WITH THE CURRENT DRY/WET SETTINGS. ORIGINAL AUDIO IS KEPT.");
        learn.onClick=[this]{if(p.engine.learningState()==1||p.engine.learningState()==5)p.stopLearn();else p.startLearn();};apply.onClick=[this]{p.applyLearn();};undo.onClick=[this]{p.undoLearn();};preview.setClickingTogglesState(true);preview.onClick=[this]{p.audition(preview.getToggleState());};
        bypass.setClickingTogglesState(true);bypassAttachment=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.apvts,"bypass",bypass);
        const char*variantNames[3][3]={{"FOCUS","BLOOM","WIDE"},{"FRONT","LIFT","MOTION"},{"SINGLE","DOUBLE","TRIPLE"}};
        for(int i=0;i<3;++i){auto&b=variants[i];b.setButtonText(variantNames[static_cast<int>(p.kind)][i]);b.setName("VARIANT "+juce::String(i+1));b.setComponentID("variant"+juce::String(i));b.onClick=[this,i]{p.setValue("variant",static_cast<float>(i));p.audition(true);preview.setToggleState(true,juce::dontSendNotification);};owner.addAndMakeVisible(b);}
        auto add=[&](const char*id,const char*label,const char*suffix){auto dial=std::make_unique<Dial>(p,id,label,suffix);owner.addAndMakeVisible(dial->slider);owner.addAndMakeVisible(dial->label);dials.push_back(std::move(dial));};
        add("amount",p.kind==CreativeKind::Reply?"DENSITY":p.kind==CreativeKind::Director?"INTENSITY":"THROW"," %");add("length",p.kind==CreativeKind::Reply?"CHOP":"TAIL"," S");add("tone","TONE"," %");add("width","WIDTH"," %");add("mix","WET"," %");add("dry","DRY"," %");add("sensitivity","DETECT"," DB");
        const char*labels[]{p.kind==CreativeKind::Reply?"SOURCE IN":"START BEAT",p.kind==CreativeKind::Reply?"SOURCE OUT":"END BEAT","MARKER LEVEL"};for(int i=0;i<3;++i){trimLabel[i].setText(labels[i],juce::dontSendNotification);trimLabel[i].setFont(font(10,true));trimLabel[i].setColour(juce::Label::textColourId,ink);owner.addAndMakeVisible(trimLabel[i]);auto&s=trim[i];s.setColour(juce::Slider::textBoxTextColourId,ink);s.setColour(juce::Slider::textBoxBackgroundColourId,cream);s.setColour(juce::Slider::textBoxOutlineColourId,sage.withAlpha(.3f));s.setSliderStyle(juce::Slider::LinearHorizontal);s.setTextBoxStyle(juce::Slider::TextBoxRight,false,62,20);s.setName(labels[i]);s.setComponentID("marker"+juce::String(i));s.setRange(0,i==2?100:p.kind==CreativeKind::Reply?300:2000,.01);owner.addAndMakeVisible(s);s.onValueChange=[this,i]{if(updating||!timeline.model.valid())return;auto&model=timeline.model;auto&m=model.markers[timeline.selected];if(i==0){if(p.kind==CreativeKind::Reply)m.startSec=std::clamp(static_cast<float>(trim[i].getValue()),0.f,m.endSec-.01f);else m.startBeat=std::clamp(static_cast<float>(trim[i].getValue()),timeline.selected>0?model.markers[timeline.selected-1].endBeat:0.f,m.endBeat-.01f);}else if(i==1){if(p.kind==CreativeKind::Reply)m.endSec=std::clamp(static_cast<float>(trim[i].getValue()),m.startSec+.01f,model.durationSeconds);else m.endBeat=std::clamp(static_cast<float>(trim[i].getValue()),m.startBeat+.01f,timeline.selected+1<model.count?model.markers[timeline.selected+1].startBeat:model.durationBeats);}else m.strength=static_cast<float>(trim[i].getValue())/100;p.editPlan(model,p.engine.isApplied());};}
        if(p.kind==CreativeKind::Phrase){const char*ids[]{"reverbSend","delaySend","delayFeedback"};const char*labels[]{"HALL SEND","DELAY SEND","FEEDBACK"};for(int i=0;i<3;++i){sends[i].setSliderStyle(juce::Slider::LinearHorizontal);sends[i].setTextBoxStyle(juce::Slider::TextBoxRight,false,62,20);sends[i].setColour(juce::Slider::textBoxTextColourId,ink);sends[i].setColour(juce::Slider::textBoxBackgroundColourId,cream);sends[i].setColour(juce::Slider::textBoxOutlineColourId,sage.withAlpha(.3f));sends[i].setTextValueSuffix(" %");sends[i].setName(labels[i]);owner.addAndMakeVisible(sends[i]);sendAttachments.push_back(std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.apvts,ids[i],sends[i]));sendLabels[i].setText(labels[i],juce::dontSendNotification);sendLabels[i].setColour(juce::Label::textColourId,ink);sendLabels[i].setFont(font(9,true));owner.addAndMakeVisible(sendLabels[i]);}
        delayRate.addItemList({"1/16 T","1/16","1/8 T","1/8","1/8 D","1/4","1/2"},1);delayRate.setName("DELAY RATE");owner.addAndMakeVisible(delayRate);delayRateAttachment=std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(p.apvts,"delayRate",delayRate);exportPart.addItemList({"HALL + DELAY","HALL WAV","DELAY WAV"},1);exportPart.setSelectedId(1);exportPart.setName("EXPORT CONTENT");owner.addAndMakeVisible(exportPart);exportPart.setTooltip("Choose the independent wet stem before RENDER FX. DRAG WAV exports that actual file.");}
