        for(int i=0;i<3;++i){bounds(trimLabel[i],22+i*204,358,194,14);bounds(trim[i],22+i*204,373,194,22);}
        for(int i=1;i<7;++i){const float x=22+(i-1)*123;bounds(dials[i]->label,x,397,116,17);bounds(dials[i]->slider,x,414,116,53);}
