        bounds(renderFx,22,502,85,25);bounds(renderMix,112,502,85,25);bounds(dragWav,202,502,85,25);bounds(previous,296,502,25,25);bounds(preset,325,502,402,25);bounds(next,732,502,25,25);bounds(status,257,56,266,17);
