GillCreativeEditor::GillCreativeEditor(GillCreativeProcessor&p):AudioProcessorEditor(&p){impl=std::make_unique<Impl>(*this,p);setResizable(true,true);setResizeLimits(impl->width,impl->height,impl->width*2,impl->height*2);if(auto*c=getConstrainer())c->setFixedAspectRatio(static_cast<double>(impl->width)/impl->height);setSize(impl->width,impl->height);}
GillCreativeEditor::~GillCreativeEditor()=default;void GillCreativeEditor::paint(juce::Graphics&g){impl->paint(g);}void GillCreativeEditor::resized(){if(impl)impl->resized();}
